            C++

    #include <iostream>
#include <vector>
using namespace std;

int Fibonacci(int a, int b, int c, int d, int n) {

    // DP array to store all terms till n
    vector<int> dp(n + 1);

    // Base cases
    dp[1] = c;
    dp[2] = d;

    // Fill DP array bottom up
    for (int i = 3; i <= n; i++)
        dp[i] = a * dp[i - 1] + b * dp[i - 2];

    return dp[n];
}

int main() {
    int a = 1, b = 1, c = 0, d = 1, n = 6;

    cout << Fibonacci(a, b, c, d, n) << endl;

    return 0;
}


