[Efficient Approach] Matrix Exponentiation - O(n) Time and O(1) SpaceRepresent the recurrence relation Gn = m*G(n-1) + n*G(n-2) as a 2×2 transformation matrix {{m, 1}, {n, 0}} to compute the nth term efficiently.The initial matrix is set up using base cases G(0) = a and G(1) = b, and the transformation matrix is raised to power (n-2) using a loop.A helper multiply function performs standard 2×2 matrix multiplication using dot product of rows and columns.After computing the required matrix power, it is multiplied with the initial matrix to get the final result.The top-left element of the resultant matrix gives the nth Generalized Fibonacci Number.
            C++

    #include <iostream>
using namespace std;

void multiply(int F[2][2], int M[2][2]) {

    // Multiply two 2x2 matrices and store result in F
    int x = F[0][0] * M[0][0] + F[0][1] * M[1][0];
    int y = F[0][0] * M[0][1] + F[0][1] * M[1][1];
    int z = F[1][0] * M[0][0] + F[1][1] * M[1][0];
    int w = F[1][0] * M[0][1] + F[1][1] * M[1][1];
    F[0][0] = x; F[0][1] = y;
    F[1][0] = z; F[1][1] = w;
}

void power(int F[2][2], int n, int a, int b) {

    // Raise transformation matrix F to the power n
    int M[2][2] = { { a, 1 }, { b, 0 } };
    for (int i = 1; i <= n; i++)
        multiply(F, M);
}

int Fibonacci(int a, int b, int c, int d, int n) {

    // Transformation matrix
    int F[2][2] = { { a, 1 }, { b, 0 } };

    // Base cases
    if (n == 1)
        return c;
    if (n == 2)
        return d;

    // Initial matrix using base case values
    int initial[2][2] = { { a * d + b * c, d }, { d, c } };

    // Raise transformation matrix to power n-2
    power(F, n - 2, a, b);

    // Multiply initial matrix with result
    multiply(initial, F);

    // Top left element is the nth term
    return initial[0][0];
}

int main() {
    int a = 1, b = 1, c = 0, d = 1, n = 6;
    cout << Fibonacci(a, b, c, d, n) << endl;
    return 0;
}


